// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz recipient and amount; we don't need special adversarial helpers because behavior is internal state change
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient admissible (any address OK, but avoid zero address isn't necessary here)
        vm.prank(address(1)); // use a caller to make the call originate from non-zero EOA
        // read prior proposalCount
        uint256 before = c.proposalCount();
        // perform the call under test
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The general property we assert: reference implementation always increments proposalCount by 1
        // So after the call, proposalCount == before + 1. We assert that property on the deployed contract c.
        // (This will pass on the reference and fail on the mutant that removed the increment for some inputs.)
        uint256 after = c.proposalCount();
        assertTrue(after == before + 1);
    }
}

