// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide but avoid zero-address being special in some logic (still allowed)
        // no tight assumptions — property should hold for all inputs
        uint256 before = c.proposalCount();
        // call as fuzzed caller
        vm.prank(msg.sender);
        // drive contract
        c.newGrantProposal(recipient, amount);
        uint256 after = c.proposalCount();
        // General invariant: proposalCount must increase by exactly 1 after newGrantProposal
        assertTrue(after == before + 1);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the contract: init, create a grant proposal, trigger finalising, then assert the grant cap condition
    function run(address vader, address usdv, address vault, address recipient, uint amount) public {
        // initialize
        c.init(vader, usdv, vault);

        // create a GRANT proposal
        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();

        // vote to trigger finalising (voteProposal will call _finalise when quorum/majority met)
        // We cannot control vault weights here; assume calling voteProposal once is enough to execute _finalise on P
        c.voteProposal(pid);

        // advance time isn't possible here; call finaliseProposal which requires cool-off passed; since coolOffPeriod is 1 and block time may have advanced,
        // calling finaliseProposal will either revert due to cool-off or proceed. To make the asserting condition machine-checkable and target the mutant change,
        // we check the grant cap via public USDV balance of the VAULT: in original contract finaliseProposal will call grantFunds which requires amount <= balance/10.
        // So we assert that the created grant amount is <= USDV.balanceOf(VAULT)/10.

        uint vaultBal = iERC20(c.USDV()).balanceOf(c.VAULT());
        // The distinguishing property: original contract enforces grant.amount <= vaultBal/10 before granting — so this holds for the proposal to be finalised without revert.
        // Mutant removed assignment to VADER in init; that doesn't directly change USDV balances, but it breaks flows that rely on VADER being set and can change behavior;
        // to ensure the test is sensitive to the mutation we assert the cap relation which must hold for successful finalisation on original.
        assert(amount <= vaultBal / 10);
    }

    // Allow reading public getters used above
    receive() external payable {}
}
